



SELECT
    'INSERT INTO chart_of_accounts_templates ' ||
    '(account_code, account_name, account_type, normal_balance, parent_template_id, account_level, is_header, is_postable) VALUES (' ||
    quote_literal(account_code) || ', ' ||
    quote_literal(account_name) || ', ' ||
    quote_literal(account_type) || ', ' ||
    quote_literal(normal_balance) || ', ' ||
    COALESCE(quote_literal(parent_template_id::text), 'NULL') || ', ' ||
    account_level || ', ' ||
    is_header || ', ' ||
    is_postable ||
    ');'
FROM chart_of_accounts_templates
ORDER BY account_code asc


SELECT string_agg(
    'INSERT INTO chart_of_accounts_templates ' ||
    '(account_code, account_name, account_type, normal_balance, parent_template_id, account_level, is_header, is_postable) VALUES (' ||
    quote_literal(account_code) || ', ' ||
    quote_literal(account_name) || ', ' ||
    quote_literal(account_type) || ', ' ||
    quote_literal(normal_balance) || ', ' ||
    COALESCE(quote_literal(parent_template_id::text), 'NULL') || ', ' ||
    account_level || ', ' ||
    is_header || ', ' ||
    is_postable ||
    ');',
    E'\n'
    ORDER BY account_code
)
FROM chart_of_accounts_templates;